/* data/cs-c/cs-12-07.js - GENERATED by tools/build.py from data/cs/cs-12-07.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-07"] = [{"id":"cs-12-07-01","kind":"short","q":"What are advanced microprocessors and compare them.","marks":5,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.1"],"model":[{"t":"Advanced microprocessors are the later members of the Intel X-86 family (8086, 80286, 80386, 80486): they have a wider word, a bigger address space and more speed-up features than the 8-bit microprocessors.","m":1},{"t":"8086: 16-bit data, 20-bit address (1 MB), a small prefetch queue and no cache.","m":1},{"t":"80286: 16-bit data, 24-bit address (16 MB), and a protected mode for multitasking.","m":1},{"t":"80386: 32-bit data and 32-bit address (4 GB), virtual memory support, and a cache outside the chip.","m":1},{"t":"80486: 32-bit, with a cache and the floating point unit built into the chip, and a faster pipeline.","m":1}]},{"id":"cs-12-07-02","kind":"short","q":"What type of O.S. is required for advanced microprocessors ?","marks":3,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.2"],"model":[{"t":"A multitasking (and multiuser) operating system is required, because these processors can run many programs at once.","m":1},{"t":"It must manage a large memory, use virtual memory and protect the programs from each other, using the protected mode of the processor.","m":1},{"t":"Examples: Windows and Unix/Linux.","m":1}]},{"id":"cs-12-07-03","kind":"short","q":"What is Virtual memory ?","marks":3,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.3"],"model":[{"t":"Virtual memory is a technique that lets a program use more memory than the physical memory of the computer.","m":1},{"t":"Only the parts needed now are kept in main memory and the rest stay on the disk; the processor brings them in when needed.","m":1},{"t":"The advanced microprocessors have hardware for it (memory management with segments and pages), so a program sees a very large address space.","m":1}]},{"id":"cs-12-07-04","kind":"short","q":"What is cache memory ?","marks":3,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.4"],"model":[{"t":"Cache memory is a small and very fast memory kept on the processor chip or near it.","m":1},{"t":"It keeps the instructions and data that are used most often, so the processor need not wait for the slow main memory.","m":1},{"t":"A code cache keeps instructions and a data cache keeps data; this speeds up the processing.","m":1}]},{"id":"cs-12-07-05","kind":"prog","q":"Describe Programming model for X 86 family of microprocessors.","marks":5,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.5"],"model":[{"t":"The general purpose registers AX, BX, CX and DX (16 bits; in 32-bit chips EAX, EBX, ECX, EDX); AX, BX, CX, DX can be used as two 8-bit halves.","m":1},{"t":"The pointer and index registers: SP, BP, SI and DI.","m":1},{"t":"The segment registers CS, DS, SS and ES (and FS and GS in the 80386 and later).","m":1},{"t":"The instruction pointer IP.","m":1},{"t":"The flag register: C, P, A, Z, S, T, I, D, O, and in later chips IOPL, NT, RF, VM and AC.","m":1}],"code":"  General registers      Pointer / index      Segment registers\n  AX (AH AL)             SP  stack pointer    CS  code segment\n  BX (BH BL)             BP  base pointer     DS  data segment\n  CX (CH CL)             SI  source index     SS  stack segment\n  DX (DH DL)             DI  destination idx  ES  extra segment\n\n  IP  instruction pointer\n  Flags: C P A Z S T I D O   (286: IOPL NT)  (386: RF VM)  (486: AC)"},{"id":"cs-12-07-06","kind":"short","q":"Differentiate between 8086 and 8088 microprocessors.","marks":4,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.6"],"model":[{"t":"Data bus: the 8086 has a 16-bit external data bus; the 8088 has an 8-bit external data bus (both are 16-bit inside).","m":1},{"t":"Prefetch queue: 6 bytes in the 8086 and 4 bytes in the 8088.","m":1},{"t":"Speed and cost: the 8086 moves 16 bits at a time so it is faster; the 8088 is slower but cheaper because it needs 8-bit memory and fewer chips.","m":1},{"t":"Both have a 20-bit address bus (1 MB). The 8088 was used in the first IBM PC.","m":1}]},{"id":"cs-12-07-07","kind":"short","q":"Differentiate between 80386 and 80486 microprocessors.","marks":4,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.7"],"model":[{"t":"Both are 32-bit processors with a 32-bit address bus (4 GB of memory).","m":1},{"t":"The 80386 has no cache on the chip and needs an outside math coprocessor (80387) for floating point work.","m":1},{"t":"The 80486 has an on-chip cache (8 KB) and a floating point unit built into the chip.","m":1},{"t":"The 80486 has a better pipeline, so it does more work in each clock period and is faster.","m":1}]},{"id":"cs-12-07-08","kind":"short","q":"What is role of instruction pointer in 8088 microprocessors ?","marks":3,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.8"],"model":[{"t":"The instruction pointer (IP) holds the offset (the position) of the next instruction inside the code segment.","m":1},{"t":"The physical address of the next instruction is found from the code segment register CS and IP.","m":1},{"t":"IP increases after each instruction is fetched, and a jump or call changes it.","m":1}]},{"id":"cs-12-07-09","kind":"short","q":"What is advantage of prefetch queue ?","marks":3,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.9"],"model":[{"t":"The prefetch queue is a small memory in which the next instructions are fetched in advance, while the processor is busy with the present instruction.","m":1},{"t":"So the next instruction is already ready and the processor does not wait for a fetch cycle.","m":1},{"t":"This speeds up the execution time.","m":1}]},{"id":"cs-12-07-10","kind":"short","q":"What are segment registers ?","marks":3,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.10"],"model":[{"t":"Segment registers hold the starting (base) address of the segments of memory: CS (code), DS (data), SS (stack) and ES (extra); the 80386 adds FS and GS.","m":1},{"t":"A segment is a block of up to 64 KB of memory.","m":1},{"t":"The physical address is made from the segment register and an offset: segment x 16 + offset.","m":1}]},{"id":"cs-12-07-m11b","kind":"mcq","q":"The maximum physical memory space which can be addressed by the 286 is ...........","marks":1,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.11(b)"],"options":["640 K bytes","1M bytes","16 M bytes","All of these."],"ans":2,"why":"The 80286 has a 24-bit address bus, so it can address 2 to the power 24 = 16 MB."},{"id":"cs-12-07-m11c","kind":"mcq","q":"The first X 86 advanced microprocessor to use full 32 bit data words was ...........","marks":1,"src":["Guide ch.7 Introduction to Intel X-86 Family, Q.11(c)"],"options":["8086","286","386","486"],"ans":2,"why":"The 8086 and the 286 are 16-bit processors. The 386 was the first X-86 processor with full 32-bit data words."},{"id":"cs-12-07-p901","kind":"short","q":"Compare 80286 and 80486 processors on the following attributes :\ni) Data bus\nii) Address bus\niii) Physical memory size","marks":3,"src":["HSC March 2023 Paper II, Q.3A(c)"],"model":[{"t":"Data bus: the 80286 has a 16-bit data bus; the 80486 has a 32-bit data bus.","m":1},{"t":"Address bus: the 80286 has a 24-bit address bus; the 80486 has a 32-bit address bus.","m":1},{"t":"Physical memory: the 80286 can address 16 MB (2 to the power 24); the 80486 can address 4 GB (2 to the power 32).","m":1}]},{"id":"cs-12-07-p902","kind":"prog","q":"Draw and label the programming model of 80486 Processor.","marks":4,"src":["HSC March 2023 Paper II, Q.3B(b)"],"model":[{"t":"The 80486 is a 32-bit processor, so its general purpose registers are 32 bits: EAX, EBX, ECX, EDX, ESI, EDI, EBP and ESP (the lower 16 bits keep the names AX, BX, CX, DX, SI, DI, BP, SP).","m":1},{"t":"Six 16-bit segment registers: CS, SS, DS, ES, FS and GS.","m":1},{"t":"The 32-bit instruction pointer EIP and the 32-bit flag register EFLAGS.","m":1},{"t":"A neat diagram with the register names and bit sizes is drawn, as below.","m":1}],"code":"  31            16 15      8 7      0\n  [   EAX            AX (AH | AL)   ]   accumulator\n  [   EBX            BX (BH | BL)   ]   base\n  [   ECX            CX (CH | CL)   ]   count\n  [   EDX            DX (DH | DL)   ]   data\n  [   ESI            SI             ]   source index\n  [   EDI            DI             ]   destination index\n  [   EBP            BP             ]   base pointer\n  [   ESP            SP             ]   stack pointer\n\n  Segment registers (16 bit):  CS  SS  DS  ES  FS  GS\n  [   EIP  ]  instruction pointer (32 bit)\n  [ EFLAGS ]  flag register (32 bit)"},{"id":"cs-12-07-p903","kind":"prog","q":"Draw and label programming model of 80286 Microprocessor.","marks":3,"src":["HSC March 2024 Paper II, Q.4A(c)"],"model":[{"t":"The 80286 is a 16-bit processor. Its general registers are the 16-bit AX, BX, CX and DX (each with a high and a low byte), and the pointer and index registers SP, BP, SI and DI.","m":1},{"t":"The segment registers are CS, DS, SS and ES (16 bit), with the 16-bit instruction pointer IP and the 16-bit flag register.","m":1},{"t":"In protected mode it also has a machine status word and the descriptor table registers. The diagram below shows the labelled registers.","m":1}],"code":"  15        8 7       0\n  [  AH  |  AL  ]  AX  accumulator\n  [  BH  |  BL  ]  BX  base\n  [  CH  |  CL  ]  CX  count\n  [  DH  |  DL  ]  DX  data\n  [     SP      ]  stack pointer\n  [     BP      ]  base pointer\n  [     SI      ]  source index\n  [     DI      ]  destination index\n\n  [ CS ] code segment    [ DS ] data segment\n  [ SS ] stack segment   [ ES ] extra segment\n  [ IP ] instruction pointer\n  [ FLAGS ] flag register\n  [ MSW ] machine status word"},{"id":"cs-12-07-p904","kind":"short","q":"Explain following features of Pentium Microprocessor:\ni) Dual Pipeline\nii) On-chip cache\niii) Branch Prediction\niv) 64-bit data bus","marks":4,"src":["HSC March 2024 Paper II, Q.4B(b)"],"model":[{"t":"Dual pipeline: the Pentium has two integer pipelines (U and V), so it can finish two instructions in one clock cycle (superscalar).","m":1},{"t":"On-chip cache: it has a separate 8 KB instruction cache and 8 KB data cache inside the chip, so memory is read less often.","m":1},{"t":"Branch prediction: a branch target buffer guesses the result of a jump, so the pipeline keeps filling with the instructions that are likely to follow.","m":1},{"t":"64-bit data bus: it brings 64 bits from the memory in one transfer (although its registers are 32 bits), so the data comes faster.","m":1}]}];
